using System.Globalization;
using DiffBeacon.Core;
using CompareOptions = DiffBeacon.Core.CompareOptions;

static class InlineDiffTests
{
    public static void Run(Action<string, Action> test)
    {
        static void Check(bool value) { if (!value) throw new Exception("Inline diff assertion failed."); }
        static void Throws<T>(Action action) where T : Exception { try { action(); } catch (T) { return; } throw new Exception("Expected " + typeof(T).Name); }
        static InlineDiffResult Detail(string a, string b, HighlightGranularity g = HighlightGranularity.Character, CompareOptions? o = null, InlineDiffLimits? limits = null) => InlineDifferences.Compare(new([new(1, 1, a, b, Change.Changed)], false), o ?? new(), g, limits: limits);
        test("Inline character only changed graphemes", () => { var r = Detail("a😀e\u0301z", "a🚀o\u0301z").Rows[0]; Check(r.Left.SequenceEqual(new[] { new TextSpan(1, 4) }) && r.Right.SequenceEqual(new[] { new TextSpan(1, 4) })); });
        test("Inline emoji ZWJ cluster remains whole", () => { var r = Detail("x👩‍💻y", "x👨‍💻y").Rows[0]; Check(r.Left.SequenceEqual(new[] { new TextSpan(1, 5) })); });
        test("Inline words numbers marks and punctuation", () => { var r = Detail("one, two42!", "one; THREE!", HighlightGranularity.Word).Rows[0]; Check(r.Left.SequenceEqual(new[] { new TextSpan(3, 1), new TextSpan(5, 5) }) && r.Right.SequenceEqual(new[] { new TextSpan(3, 1), new TextSpan(5, 5) })); });
        test("Inline whitespace run raw indices", () => { var r = Detail("a \t b", "a  b", HighlightGranularity.Word).Rows[0]; Check(r.Left.SequenceEqual(new[] { new TextSpan(1, 3) }) && r.Right.SequenceEqual(new[] { new TextSpan(1, 2) })); });
        test("Inline ignore whitespace joins equal words", () => { var r = Detail("he llo old", "hello new", HighlightGranularity.Word, new(IgnoreWhitespace: true)).Rows[0]; Check(r.Left.SequenceEqual(new[] { new TextSpan(0, 2), new TextSpan(3, 3), new TextSpan(7, 3) })); var equal = Detail("he llo", "HELLO", HighlightGranularity.Word, new(true, true)); Check(equal.Rows[0].Left.Count == 0 && equal.Rows[0].Right.Count == 0); });
        test("Inline ignored whitespace never highlighted", () => { var r = Detail("a b!", "ab?", HighlightGranularity.Word, new(IgnoreWhitespace: true)).Rows[0]; Check(r.Left.SequenceEqual(new[] { new TextSpan(3, 1) }) && r.Right.SequenceEqual(new[] { new TextSpan(2, 1) })); });
        test("Inline normalization precedes grapheme grouping", () => { var r = Detail("a \u0301", "a\u0301", HighlightGranularity.Character, new(IgnoreWhitespace: true)); Check(r.Rows[0].Left.Count == 0 && r.Rows[0].Right.Count == 0); });
        test("Inline empty insert delete and CRLF offsets", () => { Check(Detail("", "x").Rows[0].Right.SequenceEqual(new[] { new TextSpan(0, 1) })); Check(Detail("x", "").Rows[0].Left.Count == 1); var r = Detail("a\r\nx", "a\r\ny").Rows[0]; Check(r.Left.SequenceEqual(new[] { new TextSpan(3, 1) })); });
        test("Inline row order equal unilateral and line", () => { var rows = new[] { new DiffRow(1, 1, "a", "a", Change.Equal), new DiffRow(2, null, "abc", null, Change.LeftOnly), new DiffRow(3, 2, "xy", "zz", Change.Changed) }; var r = InlineDifferences.Compare(new(rows, false), new(), HighlightGranularity.Line); Check(r.Rows.Count == 3 && r.Rows[0].Left.Count == 0 && r.Rows[1].Left[0] == new TextSpan(0, 3) && r.Rows[2].Right[0] == new TextSpan(0, 2)); });
        test("Inline token and pair budgets before cells", () => { foreach (var limits in new[] { new InlineDiffLimits(MaxTokensPerPair: 1), new InlineDiffLimits(MaxCellsPerPair: 3), new InlineDiffLimits(MaxTotalCells: 3) }) { var r = Detail("a", "b", limits: limits); Check(r.FallbackLines == 1 && r.CellsUsed == 0 && r.Rows[0].IsFallback && r.Rows[0].FallbackReason != null); } });
        test("Inline aggregate cell and span budgets", () => { var rows = new[] { new DiffRow(1, 1, "a", "b", Change.Changed), new DiffRow(2, 2, "c", "d", Change.Changed) }; var r = InlineDifferences.Compare(new(rows, false), new(), HighlightGranularity.Character, limits: new(MaxTotalCells: 4)); Check(r.CellsUsed == 4 && r.FallbackLines == 1 && !r.Rows[0].IsFallback); Check(Detail("axa", "aya", limits: new(MaxTotalSpans: 1)).FallbackLines == 1); r = InlineDifferences.Compare(new(rows, false), new(), HighlightGranularity.Character, limits: new(MaxTotalSpans: 2)); Check(!r.Rows[0].IsFallback && r.Rows[1].IsFallback); });
        test("Inline bounded character allocation", () => { string a = new('a', 100_000), b = new('b', 100_000); Detail("a", "b"); long before = GC.GetAllocatedBytesForCurrentThread(); var r = Detail(a, b, limits: new(MaxTokensPerPair: 32)); long bytes = GC.GetAllocatedBytesForCurrentThread() - before; Console.WriteLine($"Inline character allocation: {bytes} bytes"); Check(r.FallbackLines == 1 && r.CellsUsed == 0 && bytes < 1_000_000); });
        test("Inline punctuation and shared pair token limit", () => { string a = new('!', 100_000); long before = GC.GetAllocatedBytesForCurrentThread(); var bounded = Detail(a, "?", HighlightGranularity.Word, limits: new(MaxTokensPerPair: 32)); Check(bounded.FallbackLines == 1 && GC.GetAllocatedBytesForCurrentThread() - before < 1_000_000); Check(Detail("ab", "cd", limits: new(MaxTokensPerPair: 4)).FallbackLines == 0); Check(Detail("ab", "cd", limits: new(MaxTokensPerPair: 3)).Rows[0].FallbackReason == "Token budget exceeded"); });
        test("Inline bounded huge word allocation", () => { string a = new('a', 100_000), b = new('b', 100_000); Detail("a", "b", HighlightGranularity.Word); long before = GC.GetAllocatedBytesForCurrentThread(); var r = Detail(a, b, HighlightGranularity.Word); long bytes = GC.GetAllocatedBytesForCurrentThread() - before; Console.WriteLine($"Inline word allocation: {bytes} bytes"); Check(r.FallbackLines == 0 && r.Rows[0].Left.SequenceEqual(new[] { new TextSpan(0, a.Length) }) && bytes < 4_000_000); });
        test("Inline bounded ignored whitespace provenance", () => { string a = string.Concat(Enumerable.Repeat("a ", 50_000)), b = "b"; long before = GC.GetAllocatedBytesForCurrentThread(); var r = Detail(a, b, HighlightGranularity.Word, new(IgnoreWhitespace: true), new(MaxTotalSpans: 8)); long bytes = GC.GetAllocatedBytesForCurrentThread() - before; Console.WriteLine($"Inline whitespace allocation: {bytes} bytes"); Check(r.FallbackLines == 1 && r.Rows[0].FallbackReason == "Total span budget exceeded" && r.CellsUsed == 0 && bytes < 1_000_000); });
        test("Inline normalized equality precedes budgets", () => { foreach (var g in new[] { HighlightGranularity.Character, HighlightGranularity.Word }) { var r = Detail("a \u0301𐐨", "a\u0301𐐀", g, new(true, true), new(0, 0, 0, 0)); Check(r.FallbackLines == 0 && r.Rows[0].Left.Count == 0 && r.Rows[0].Right.Count == 0); } });
        test("Inline malformed UTF16 remains highlightable", () => { foreach (var g in new[] { HighlightGranularity.Character, HighlightGranularity.Word }) { var r = Detail("a\ud800z", "a\udc00z", g).Rows[0]; Check(r.Left.SequenceEqual(new[] { new TextSpan(1, 1) }) && r.Right.SequenceEqual(new[] { new TextSpan(1, 1) })); } });
        test("Inline oversized and invalid budgets", () => { Check(Detail("a", "b", limits: new(int.MaxValue, long.MaxValue, long.MaxValue, int.MaxValue)).FallbackLines == 0); foreach (var limits in new[] { new InlineDiffLimits(MaxTokensPerPair: -1), new InlineDiffLimits(MaxCellsPerPair: -1), new InlineDiffLimits(MaxTotalCells: -1), new InlineDiffLimits(MaxTotalSpans: -1) }) Throws<ArgumentOutOfRangeException>(() => Detail("a", "b", limits: limits)); });
        test("Inline oversized cell storage falls back before int cast", () => { var r = Detail(new string('a', 46_340), new string('b', 46_340), limits: new(int.MaxValue, long.MaxValue, long.MaxValue, int.MaxValue)); Check(r.CellsUsed == 0 && r.Rows[0].FallbackReason == "Cell storage budget exceeded"); });
        test("Inline deterministic valid grapheme spans", () => { string[] values = ["", "a", "ababa", "a😀b", "e\u0301o\u0301", "👩‍💻!", " \tq", "a\r\nb"]; foreach (var a in values) foreach (var b in values) foreach (var g in new[] { HighlightGranularity.Character, HighlightGranularity.Word }) { var r = Detail(a, b, g); var again = Detail(a, b, g); Check(r.Rows[0].Left.SequenceEqual(again.Rows[0].Left)); foreach (var pair in new[] { (a, r.Rows[0].Left), (b, r.Rows[0].Right) }) { var boundaries = StringInfo.ParseCombiningCharacters(pair.Item1).Append(pair.Item1.Length).ToHashSet(); int end = 0; foreach (var s in pair.Item2) { Check(s.Start >= end && s.Length > 0 && s.Start + s.Length <= pair.Item1.Length && boundaries.Contains(s.Start) && boundaries.Contains(s.Start + s.Length)); end = s.Start + s.Length; } } } });
        test("Inline cancellation empty and all ignored", () => { var cancelled = new CancellationToken(true); Throws<OperationCanceledException>(() => InlineDifferences.Compare(new([], false), new(), HighlightGranularity.Word, cancelled)); Throws<OperationCanceledException>(() => InlineDifferences.Compare(new([new(1, 1, "   ", "\t", Change.Changed)], false), new(IgnoreWhitespace: true), HighlightGranularity.Character, cancelled)); Throws<OperationCanceledException>(() => TextComparison.Compare("", "", new(IgnoreBlankLines: true), cancelled)); Throws<OperationCanceledException>(() => TextComparison.Compare(new string(' ', 100000), "", new(IgnoreBlankLines: true), cancelled)); });
        test("Scroll maps paired anchors roundtrip and monotonic gaps", () => { foreach (var pair in new[] { ("a\nb", "first\na\nb\nlast"), ("first\na\nb\nlast", "a\nb"), ("\na\n\nb\n", "a\nb"), ("a\nX\nb", "a\nb") }) { var result = TextComparison.Compare(pair.Item1, pair.Item2, new(IgnoreBlankLines: true)); int ac = TextComparison.Lines(pair.Item1).Length, bc = TextComparison.Lines(pair.Item2).Length; var map = TextScrollMap.Create(result, ac, bc); int previous = 0; for (int i = -1; i <= ac; i++) { int mapped = map.MapLeftToRight(i); Check(mapped >= previous && mapped < bc); previous = mapped; } previous = 0; for (int i = -1; i <= bc; i++) { int mapped = map.MapRightToLeft(i); Check(mapped >= previous && mapped < ac); previous = mapped; } foreach (var row in result.Rows.Where(r => r.LeftLine.HasValue && r.RightLine.HasValue)) { Check(map.MapLeftToRight(row.LeftLine!.Value - 1) == row.RightLine!.Value - 1); Check(map.MapRightToLeft(row.RightLine.Value - 1) == row.LeftLine.Value - 1); } } });
        test("Scroll empty and absent anchors clamp", () => { var map = TextScrollMap.Create(new([], false), 0, 0); Check(map.MapLeftToRight(-1) == 0 && map.MapRightToLeft(999) == 0); map = TextScrollMap.Create(new([], false), 3, 4); Check(map.MapLeftToRight(99) == 0 && map.MapRightToLeft(-99) == 0); });
        test("Merge proposal prevalidates and preserves snapshots", () => { string original = "abc"; Check(TextEditProposal.Replace(original, 1, 1, "XYZ", "") == "aXYZc" && original == "abc"); Throws<ArgumentOutOfRangeException>(() => TextEditProposal.Replace(original, 3, 1, "", "")); Throws<InvalidDataException>(() => TextEditProposal.Replace(original, 0, 0, new string('x', 2_000_000), "")); Throws<InvalidDataException>(() => TextEditProposal.Replace("", 0, 0, "x", new string('y', TextComparison.MaxCharacters))); Throws<InvalidDataException>(() => TextEditProposal.Replace(original, 0, 0, new string('\n', TextComparison.MaxLines), "")); Check(original == "abc"); });
        test("Merge proposal exact editor and combined boundaries", () => { Check(TextEditProposal.Replace("", 0, 0, new string('x', 2_000_000), new string('y', 2_000_000)).Length == 2_000_000); Check(TextEditProposal.Replace("", 0, 0, new string('\n', 49_999), new string('\n', 49_999)).Length == 49_999); Throws<InvalidDataException>(() => TextEditProposal.Replace("", 0, 0, new string('\n', 50_000), new string('\n', 49_999))); });
        test("Session v1 v2 defaults and v3 preferences roundtrip", () => { string dir = Path.Combine(Path.GetTempPath(), "diffbeacon-inline-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(dir); try { foreach (int version in new[] { 1, 2, 3 }) { string path = Path.Combine(dir, "s.json"); var s = new Session(version, "test", "Text", "a", "b", new()); s.Save(path); Check(Session.Load(path) == s); File.WriteAllText(path, "{\"Version\":" + version + ",\"Name\":\"test\",\"Mode\":\"Tables\",\"Left\":\"a\",\"Right\":\"b\",\"Options\":{}}"); var old = Session.Load(path); Check(old.Granularity == HighlightGranularity.Line && old.SyncScrolling && !old.WordWrap && old.TableSeparator == ","); } var modern = new Session(3, "test", "Tables", "a", "b", new(), "*.cs", "bin", HighlightGranularity.Word, false, true, "\t"); modern.Save(Path.Combine(dir, "modern.json")); Check(Session.Load(Path.Combine(dir, "modern.json")) == modern); foreach (int version in new[] { 1, 2 }) foreach (var s in new[] { new Session(version, "test", "Text", "", "", new(), Granularity: HighlightGranularity.Character), new Session(version, "test", "Text", "", "", new(), SyncScrolling: false), new Session(version, "test", "Text", "", "", new(), WordWrap: true), new Session(version, "test", "Tables", "", "", new(), TableSeparator: "\t") }) Throws<InvalidDataException>(() => s.Save(Path.Combine(dir, "invalid.json"))); foreach (string separator in new[] { "", "ab", "\"", "\r", "\n", "\0" }) Throws<InvalidDataException>(() => (modern with { TableSeparator = separator }).Save(Path.Combine(dir, "invalid.json"))); Throws<InvalidDataException>(() => (modern with { Granularity = (HighlightGranularity)99 }).Save(Path.Combine(dir, "invalid.json"))); } finally { Directory.Delete(dir, true); } });
    }
}
